while True:
 try:
  r=urllib.request.urlopen('http://subject:8000/',timeout=3); print('GET subject',r.status,flush=True)
 except urllib.error.HTTPError as e: print('GET subject',e.code,flush=True)
 except Exception as e: print('GET subject',type(e).__name__,flush=True)
 time.sleep(3)

